/* ========================================================================== */
/*  Map                                                                        */
/* ========================================================================== */

const MIN_Z = 1, MAX_Z = 14;

function MapView({ w, h, solved, target, mode, flash, natl, clim, revealAll, onAnswer }) {
  const cvs = useRef(null);
  const box = useRef(null);
  const [view, setView] = useState({ z: 1, tx: 0, ty: 0 });
  const g = useRef({ kind: null, x: 0, y: 0, moved: 0, d0: 0, z0: 1, cx: 0, cy: 0, tx0: 0, ty0: 0, last: 0 });

  const base = Math.min(w / MAP_W, h / MAP_H);
  const scale = base * view.z;

  const clampView = useCallback((v) => {
    const s = base * v.z, mw = MAP_W * s, mh = MAP_H * s;
    const tx = mw <= w ? (w - mw) / 2 : Math.min(0, Math.max(w - mw, v.tx));
    const ty = mh <= h ? (h - mh) / 2 : Math.min(0, Math.max(h - mh, v.ty));
    return { z: v.z, tx, ty };
  }, [base, w, h]);

  useEffect(() => { setView((v) => clampView(v)); }, [clampView]);

  const zoomAbout = useCallback((px, py, f) => {
    setView((v) => {
      const z = Math.max(MIN_Z, Math.min(MAX_Z, v.z * f));
      const k = z / v.z;
      return clampView({ z, tx: px - (px - v.tx) * k, ty: py - (py - v.ty) * k });
    });
  }, [clampView]);

  /* screen pixel -> lon/lat, plus the reach allowed for a near-miss */
  const tap = useCallback((px, py) => {
    const lon = (px - view.tx) / scale + MX0;
    const lat = mercLat(MY1 - (py - view.ty) / scale);
    const rad = Math.max(1, Math.min(20, Math.round(18 / (scale / PPD))));
    onAnswer(lon, lat, rad);
  }, [view, scale, onAnswer]);

  /* ---------------------------------------------------------------- draw */
  useEffect(() => {
    const cv = cvs.current; if (!cv) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    const x = cv.getContext("2d");
    x.setTransform(dpr, 0, 0, dpr, 0, 0);
    x.fillStyle = C.ocean; x.fillRect(0, 0, w, h);

    const s = scale, tx = view.tx, ty = view.ty, pad = 2;
    const red = flash && flash.red, grn = flash && flash.green;

    const RR = rowRuns;
    for (let i = 0; i < RR.length; i += 4) {
      const row = RR[i], col = RR[i + 1], len = RR[i + 2], pid = RR[i + 3];
      const y0 = (MY1 - YE[row]) * s + ty, y1 = (MY1 - YE[row + 1]) * s + ty;
      if (y1 < -pad || y0 > h + pad) continue;
      const px = (col / PPD) * s + tx, pw = (len / PPD) * s;
      if (px + pw < -pad || px > w + pad) continue;
      let fill = C.land;
      if (revealAll || solved.has(pid)) fill = ZBY[PBY[pid].z].c;
      if (mode === "type" && pid === target) fill = C.cream;
      if (red && red.has(pid)) fill = C.red;
      else if (grn && grn.has(pid)) fill = C.green;
      x.fillStyle = fill;
      x.fillRect(px, y0, pw + 0.7, y1 - y0 + 0.7);
    }

    if (clim) {
      x.save();
      x.strokeStyle = C.clim; x.lineWidth = 0.9; x.globalAlpha = 0.8;
      x.setLineDash([3, 2.4]); x.lineCap = "butt"; x.beginPath();
      const V = CLIMATE_EDGES.V;
      for (let i = 0; i < V.length; i += 3) {
        const px = (V[i] / PPD) * s + tx; if (px < -pad || px > w + pad) continue;
        const ya = (MY1 - YE[V[i + 1]]) * s + ty, yb = (MY1 - YE[V[i + 2]]) * s + ty;
        if (yb < -pad || ya > h + pad) continue;
        x.moveTo(px, ya); x.lineTo(px, yb);
      }
      const HH = CLIMATE_EDGES.H;
      for (let i = 0; i < HH.length; i += 3) {
        const py = (MY1 - YE[HH[i]]) * s + ty; if (py < -pad || py > h + pad) continue;
        const xa = (HH[i + 1] / PPD) * s + tx, xb = (HH[i + 2] / PPD) * s + tx;
        if (xb < -pad || xa > w + pad) continue;
        x.moveTo(xa, py); x.lineTo(xb, py);
      }
      x.stroke(); x.restore();
    }

    if (natl) {
      x.save();
      x.strokeStyle = C.natl; x.lineWidth = 0.75; x.globalAlpha = 0.85; x.lineJoin = "round";
      x.beginPath();
      for (const r of NATIONAL) {
        for (let i = 0; i < r.length; i += 2) {
          const px = (r[i] - MX0) * s + tx, py = (MY1 - r[i + 1]) * s + ty;
          if (i === 0) x.moveTo(px, py); else x.lineTo(px, py);
        }
        x.closePath();
      }
      x.stroke(); x.restore();
    }

    /* locator rings for regions smaller than a fingertip */
    const ring = (p, col, rad) => {
      const px = (p.mk[0] - MX0) * s + tx, py = (MY1 - mercY(p.mk[1])) * s + ty;
      x.setLineDash([]);
      x.beginPath(); x.arc(px, py, rad, 0, Math.PI * 2);
      x.strokeStyle = col; x.lineWidth = 1.5; x.stroke();
    };
    const rr = view.z < 4 ? 15 : 10;
    if (view.z < 3) for (const p of PATCHES) if (ISLE.has(p.i) && (revealAll || solved.has(p.i))) ring(p, ZBY[p.z].c, 8);
    if (mode === "type" && target && PBY[target].km < 40000) ring(PBY[target], C.cream, rr);
    if (red) red.forEach((id) => { if (PBY[id].km < 40000) ring(PBY[id], C.red, rr); });
    if (grn) grn.forEach((id) => { if (PBY[id].km < 40000) ring(PBY[id], C.green, rr); });
  }, [w, h, scale, view, solved, target, mode, flash, natl, clim, revealAll]);

  /* ------------------------------------------------------------ gestures */
  useEffect(() => {
    const el = box.current; if (!el) return;
    const rect = () => el.getBoundingClientRect();
    const dist = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);

    const startPinch = (t, r) => {
      g.current.kind = "pinch"; g.current.d0 = dist(t); g.current.z0 = view.z;
      g.current.cx = (t[0].clientX + t[1].clientX) / 2 - r.left;
      g.current.cy = (t[0].clientY + t[1].clientY) / 2 - r.top;
    };
    const onBtn = (t) => t && t.closest && t.closest(".ad-reset");

    const onStart = (e) => {
      if (onBtn(e.target)) return;
      const r = rect();
      if (e.touches.length >= 2) { startPinch([e.touches[0], e.touches[1]], r); e.preventDefault(); return; }
      const t = e.touches[0];
      g.current.kind = "maybe"; g.current.x = t.clientX; g.current.y = t.clientY;
      g.current.moved = 0; g.current.tx0 = view.tx; g.current.ty0 = view.ty;
    };
    const onMove = (e) => {
      if (g.current.kind === null) return;
      const r = rect();
      if (e.touches.length >= 2) {
        if (g.current.kind !== "pinch") startPinch([e.touches[0], e.touches[1]], r);
        const f = dist([e.touches[0], e.touches[1]]) / g.current.d0;
        const z = Math.max(MIN_Z, Math.min(MAX_Z, g.current.z0 * f));
        setView((v) => {
          const k = z / v.z;
          return clampView({ z, tx: g.current.cx - (g.current.cx - v.tx) * k, ty: g.current.cy - (g.current.cy - v.ty) * k });
        });
        e.preventDefault(); return;
      }
      if (g.current.kind === "pinch") return;
      const t = e.touches[0];
      const dx = t.clientX - g.current.x, dy = t.clientY - g.current.y;
      g.current.moved = Math.max(g.current.moved, Math.hypot(dx, dy));
      if (g.current.moved > 10) {
        g.current.kind = "pan";
        setView((v) => clampView({ z: v.z, tx: g.current.tx0 + dx, ty: g.current.ty0 + dy }));
        e.preventDefault();
      }
    };
    const onEnd = (e) => {
      if (onBtn(e.target)) { g.current.kind = null; return; }
      if (g.current.kind === "maybe" && g.current.moved <= 10) {
        const r = rect(), t = e.changedTouches[0];
        g.current.last = Date.now();
        tap(t.clientX - r.left, t.clientY - r.top);
      }
      g.current.kind = null;
    };
    const onWheel = (e) => {
      if (onBtn(e.target)) return;
      const r = rect();
      zoomAbout(e.clientX - r.left, e.clientY - r.top, e.deltaY < 0 ? 1.15 : 1 / 1.15);
      e.preventDefault();
    };
    el.addEventListener("touchstart", onStart, { passive: false });
    el.addEventListener("touchmove", onMove, { passive: false });
    el.addEventListener("touchend", onEnd);
    el.addEventListener("touchcancel", onEnd);
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
      el.removeEventListener("touchcancel", onEnd);
      el.removeEventListener("wheel", onWheel);
    };
  }, [view, clampView, zoomAbout, tap]);

  const md = useRef(null);
  const isReset = (t) => t && t.closest && t.closest(".ad-reset");
  const onMouseDown = (e) => {
    if (isReset(e.target)) return;
    md.current = { x: e.clientX, y: e.clientY, tx: view.tx, ty: view.ty, moved: 0 };
  };
  const onMouseMove = (e) => {
    const m = md.current; if (!m) return;
    const dx = e.clientX - m.x, dy = e.clientY - m.y;
    m.moved = Math.max(m.moved, Math.hypot(dx, dy));
    if (m.moved > 6) setView((v) => clampView({ z: v.z, tx: m.tx + dx, ty: m.ty + dy }));
  };
  const onMouseUp = (e) => {
    const m = md.current; md.current = null;
    if (isReset(e.target)) return;
    if (!m || m.moved > 6) return;
    if (Date.now() - g.current.last < 600) return;
    const r = box.current.getBoundingClientRect();
    tap(e.clientX - r.left, e.clientY - r.top);
  };

  return (
    <div className="ad-mapwrap" ref={box}
      onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp}
      onMouseLeave={() => { md.current = null; }}
      role="img" aria-label="Map of Africa. Climate regions stay unpainted until you identify them.">
      <canvas ref={cvs} style={{ width: w, height: h, display: "block", touchAction: "none", cursor: "crosshair" }} />
      {view.z > 1.02 && (
        <button className="ad-reset" onClick={() => setView(clampView({ z: 1, tx: 0, ty: 0 }))}>Reset view</button>
      )}
    </div>
  );
}

/* ========================================================================== */
/*  Session                                                                    */
/* ========================================================================== */

const TOTAL = PATCHES.length;
const CAMPS = [
  ["Machame Gate", 0], ["Machame Camp", 0.2], ["Shira Camp", 0.4],
  ["Barranco Wall", 0.6], ["Karanga Camp", 0.78], ["Barafu Camp", 0.92], ["Uhuru Peak", 1],
];
const shuffle = (a) => { const b = a.slice(); for (let i = b.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0;[b[i], b[j]] = [b[j], b[i]]; } return b; };
const allIds = PATCHES.map((p) => p.i);
const fmtKm = (n) => n.toLocaleString("en-US");

export default function AtlasDrillClimate() {
  const [input, setInput] = useState("tap");        // "type" | "tap"
  const [session, setSession] = useState("practice"); // "practice" | "climb"
  const [natl, setNatl] = useState(false);
  const [clim, setClim] = useState(false);
  const [keyOpen, setKeyOpen] = useState(false);

  const [queue, setQueue] = useState(() => shuffle(allIds));
  const [solved, setSolved] = useState(() => new Set());
  const [phase, setPhase] = useState("ask");        // ask | right | wrong
  const [flash, setFlash] = useState(null);
  const [note, setNote] = useState(null);           // {ok, headline, patch}
  const [nudge, setNudge] = useState("");
  const [detail, setDetail] = useState(null);   // {patch, ok} — the reading material
  const [score, setScore] = useState({ right: 0, total: 0 });
  const [guesses, setGuesses] = useState(0);
  const [typed, setTyped] = useState("");

  const wrapRef = useRef(null);
  const inputRef = useRef(null);
  const nextRef = useRef(null);
  const [size, setSize] = useState({ w: 360, h: 340 });

  useEffect(() => {
    const el = wrapRef.current; if (!el) return;
    const ro = new ResizeObserver(([e]) => {
      const cw = e.contentRect.width;
      if (cw > 0) setSize({ w: cw, h: Math.max(260, Math.min(cw / (MAP_W / MAP_H), 640)) });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const target = queue.length ? queue[0] : null;
  const tp = target ? PBY[target] : null;
  const tz = tp ? ZBY[tp.z] : null;
  const done = session === "climb" && solved.size === TOTAL;

  const remainingOf = useCallback((zk) => PATCHES.filter((p) => p.z === zk && !solved.has(p.i)).length, [solved]);

  const reset = useCallback((keepSolved) => {
    const s = keepSolved ? solved : new Set();
    setSolved(s);
    setQueue(shuffle(allIds.filter((i) => !s.has(i))));
    setPhase("ask"); setFlash(null); setNote(null); setNudge(""); setTyped(""); setDetail(null);
    if (!keepSolved) { setScore({ right: 0, total: 0 }); setGuesses(0); }
  }, [solved]);

  /* the climb survives a change of answering style; only the question resets */
  const switchInput = (k) => {
    setInput(k); setPhase("ask"); setFlash(null); setNote(null); setNudge(""); setTyped("");
  };

  const switchSession = (s) => { setSession(s); setSolved(new Set()); setQueue(shuffle(allIds)); setPhase("ask"); setFlash(null); setNote(null); setNudge(""); setTyped(""); setDetail(null); setScore({ right: 0, total: 0 }); setGuesses(0); };

  /* ---------------------------------------------------------- scoring ---- */
  const advance = useCallback((solvedId) => {
    setPhase("ask"); setFlash(null); setNudge(""); setTyped("");
    setQueue((q) => {
      if (session === "climb") {
        const nxt = q.filter((i) => i !== solvedId);
        return nxt;
      }
      const rest = q.slice(1);
      return rest.length <= 1 ? shuffle(allIds) : rest;
    });
  }, [session]);

  const succeed = useCallback((pid) => {
    const p = PBY[pid];
    setGuesses((g) => g + 1);
    setScore((s) => ({ right: s.right + 1, total: s.total + 1 }));
    setFlash({ green: new Set([pid]) });
    setNote({ ok: true, patch: p });
    setDetail({ patch: p, ok: true });
    setPhase("right");
    if (session === "climb") setSolved((s) => { const n = new Set(s); n.add(pid); return n; });
  }, [session]);

  const fail = useCallback((gotId, gotZoneKey, openWater, answerId) => {
    const ansId = answerId || target;
    const ans = ansId ? PBY[ansId] : tp;
    setGuesses((g) => g + 1);
    setScore((s) => ({ ...s, total: s.total + 1 }));
    setFlash({ red: gotId ? new Set([gotId]) : new Set(), green: ansId ? new Set([ansId]) : new Set() });
    setNote({
      ok: false, patch: ans,          // the nearest correct region to the tap
      gotPatch: gotId ? PBY[gotId] : null,   // a specific wrong region, when one was tapped
      gotZone: gotZoneKey ? ZBY[gotZoneKey] : null, // a named wrong zone, when one was typed
      openWater,
    });
    setDetail({ patch: ans, ok: false });
    setPhase("wrong");
  }, [target, tp]);

  const next = () => {
    setPhase("ask"); setFlash(null); setNudge(""); setTyped(""); setNote(null);
    setQueue((q) => {
      const rest = q.slice(1);
      if (session === "climb") return [...rest, q[0]];
      return rest.length <= 1 ? shuffle(allIds) : rest;
    });
  };

  /* ---------------------------------------------------------- answering -- */
  const onMapAnswer = useCallback((lon, lat, rad) => {
    if (input !== "tap" || phase !== "ask" || !tp) return;
    const pid = resolveTap(lon, lat, rad, tp.z);
    const nearest = nearestZonePatch(lon, lat, tp.z, session === "climb" ? solved : null);
    if (!pid) { fail(0, null, true, nearest); return; }
    const p = PBY[pid];
    if (p.z === tp.z) {
      if (session === "climb" && solved.has(pid)) { setNudge(`${p.n} is already on the map — find another.`); return; }
      succeed(pid);
    } else {
      fail(pid, null, false, nearest);
    }
  }, [input, phase, tp, session, solved, succeed, fail]);

  const submitTyped = () => {
    if (phase !== "ask" || !tp) return;
    const k = ANSWERS[norm(typed)];
    if (!k) { setNudge(typed.trim() ? "Not a climate zone I know. Open the zone key for the list." : ""); return; }
    if (k === tp.z) succeed(target);
    else fail(0, k, false);
  };

  useEffect(() => {
    if (input === "type" && phase === "ask" && inputRef.current) inputRef.current.focus();
    /* after an answer the Next button takes focus, so Enter carries straight on */
    if (phase !== "ask" && nextRef.current) nextRef.current.focus();
  }, [input, phase, target]);

  const metres = Math.round((solved.size / TOTAL) * 5895);
  const frac = solved.size / TOTAL;

  /* ------------------------------------------------------------ render --- */
  return (
    <div className="ad-root">
      <style>{CSS}</style>
      <div className="ad-panel">

        <header className="ad-head">
          <h1>Atlas Drill</h1>
          <p className="ad-sub">African climates &middot; Köppen–Geiger &middot; {TOTAL} regions</p>
        </header>

        <div className="ad-modes">
          <div className="ad-seg" role="group" aria-label="How you answer">
            <button className={input === "type" ? "on" : ""} onClick={() => switchInput("type")}>Name it</button>
            <button className={input === "tap" ? "on" : ""} onClick={() => switchInput("tap")}>Find it</button>
          </div>
          <div className="ad-seg" role="group" aria-label="How the session is scored">
            <button className={session === "practice" ? "on" : ""} onClick={() => switchSession("practice")}>Practice</button>
            <button className={session === "climb" ? "on" : ""} onClick={() => switchSession("climb")}>Kilimanjaro</button>
          </div>
        </div>

        {session === "climb" ? (
          <div className="ad-climb">
            <div className="ad-alt"><span className="num">{fmtKm(metres)}</span><span className="unit">m</span>
              <span className="ad-of">{solved.size} of {TOTAL} regions</span></div>
            <div className="ad-bar">
              <div className="ad-fill" style={{ width: `${frac * 100}%` }} />
              {CAMPS.map(([n, f]) => (
                <span key={n} className={"ad-camp" + (frac >= f ? " hit" : "")} style={{ left: `${f * 100}%` }} title={n} />
              ))}
            </div>
            <div className="ad-camplab">{CAMPS.filter(([, f]) => frac >= f).slice(-1)[0]?.[0] || "Machame Gate"}</div>
          </div>
        ) : (
          <div className="ad-tally">
            <span className="num">{score.right}</span>
            <span className="ad-of">/ {score.total} &nbsp;{score.total ? Math.round((score.right / score.total) * 100) + "%" : ""}</span>
          </div>
        )}

        <div className="ad-columns">

        <div className="ad-col-ask">
        {done ? (
          <div className="ad-summit">
            <h2>Uhuru Peak, 5,895 m</h2>
            <p>All {TOTAL} regions placed, in {guesses} guesses. The map below is the real Köppen–Geiger climate map of Africa, drawn entirely by you.</p>
            <button className="ad-primary" onClick={() => switchSession("climb")}>Climb again</button>
          </div>
        ) : (
          <div className="ad-prompt">
            {input === "tap" && tp && (
              <>
                <div className="ad-ask">Find a region of</div>
                <div className="ad-zone" style={{ color: tz.c }}>{tz.n}</div>
                <div className="ad-meta">
                  <span className="kp">{tz.kp}</span>
                  {session === "climb"
                    ? <span>{remainingOf(tp.z)} of {ZONE_COUNT[tp.z]} still unpainted</span>
                    : <span>{ZONE_COUNT[tp.z]} regions on this map</span>}
                </div>
                <div className="ad-nudge">{phase === "ask" ? nudge : "\u00A0"}</div>
              </>
            )}
            {input === "type" && tp && (
              <>
                <div className="ad-ask">What climate is the highlighted region?</div>
                <div className="ad-row">
                  <input ref={inputRef} className="ad-input" value={typed} placeholder="savanna, hot desert, fynbos…"
                    disabled={phase !== "ask"}
                    onChange={(e) => { setTyped(e.target.value); setNudge(""); }}
                    onKeyDown={(e) => { if (e.key === "Enter") submitTyped(); }}
                    autoCapitalize="none" autoCorrect="off" autoComplete="off" spellCheck="false"
                    aria-label="Climate zone name" />
                  <button className="ad-primary" onClick={submitTyped} disabled={phase !== "ask"}>Check</button>
                </div>
                <div className="ad-nudge">{phase === "ask" ? nudge : "\u00A0"}</div>
              </>
            )}
          </div>
        )}
        </div>

        <div className="ad-col-map">
        <div className="ad-mapwrapouter" ref={wrapRef}>
          <MapView
            w={size.w} h={size.h}
            solved={solved} target={target} mode={input}
            flash={flash} natl={natl} clim={clim}
            revealAll={done}
            onAnswer={onMapAnswer}
          />
        </div>

        <div className="ad-toggles">
          <button className={"ad-tog" + (natl ? " on" : "")} aria-pressed={natl} onClick={() => setNatl((v) => !v)}>
            <span className="sw solid" /> National borders
          </button>
          <button className={"ad-tog" + (clim ? " on" : "")} aria-pressed={clim} onClick={() => setClim((v) => !v)}>
            <span className="sw dotted" /> Climate borders
          </button>
          <button className="ad-tog" aria-expanded={keyOpen} onClick={() => setKeyOpen((v) => !v)}>
            {keyOpen ? "Hide zone key" : "Zone key"}
          </button>
        </div>
        </div>

        <div className="ad-col-answer">
        {phase !== "ask" && note && (
          <div className="ad-outcome">
            <button className="ad-primary ad-nextbtn" ref={nextRef}
              onClick={() => (note.ok ? advance(note.patch.i) : next())}>Next</button>
            {note.ok ? (
              <div className="ad-pick ok solo">
                <div className="ad-picklab">Correct</div>
                <div className="ad-rname">{note.patch.n}</div>
                <div className="ad-rzone" style={{ color: ZBY[note.patch.z].c }}>
                  {ZBY[note.patch.z].n} · {ZBY[note.patch.z].kp}
                </div>
              </div>
            ) : (
              <div className="ad-pickrow">
                <div className="ad-pick no">
                  <div className="ad-picklab">You picked</div>
                  {note.openWater && <div className="ad-rname">Open water</div>}
                  {note.gotPatch && (
                    <>
                      <div className="ad-rname">{note.gotPatch.n}</div>
                      <div className="ad-rzone" style={{ color: ZBY[note.gotPatch.z].c }}>
                        {ZBY[note.gotPatch.z].n} · {ZBY[note.gotPatch.z].kp}
                      </div>
                    </>
                  )}
                  {note.gotZone && (
                    <div className="ad-rname" style={{ color: note.gotZone.c }}>{note.gotZone.n}</div>
                  )}
                </div>
                <div className="ad-pick ok">
                  <div className="ad-picklab">Correct answer</div>
                  <div className="ad-rname">{note.patch.n}</div>
                  <div className="ad-rzone" style={{ color: ZBY[note.patch.z].c }}>
                    {ZBY[note.patch.z].n} · {ZBY[note.patch.z].kp}
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {detail && (
          <div className="ad-last">
            <div className="ad-lastlab">{detail.ok ? "Last found" : "The answer"}</div>
            <div className="ad-rname">{detail.patch.n}</div>
            <div className="ad-rzone" style={{ color: ZBY[detail.patch.z].c }}>
              {ZBY[detail.patch.z].n} · {ZBY[detail.patch.z].kp}
            </div>
            <p className="ad-blurb">{detail.patch.d}</p>
            <div className="ad-facts">
              <span>{fmtKm(detail.patch.km)} km²</span><span>{detail.patch.cs.join(" · ")}</span>
            </div>
            <div className="ad-wwf">{ZBY[detail.patch.z].wwf}</div>
          </div>
        )}
        </div>
        </div>

        {keyOpen && (
          <div className="ad-key">
            {ZONES.map((z) => {
              const found = ZONE_COUNT[z.k] - remainingOf(z.k);
              return (
                <div className="ad-keyrow" key={z.k}>
                  <span className="ad-swatch" style={{ background: z.c }} />
                  <div className="ad-keytext">
                    <div className="ad-keyname">{z.n} <span className="kp">{z.kp}</span></div>
                    <div className="ad-keywwf">{z.wwf}</div>
                    <div className="ad-keydesc">{z.d}</div>
                  </div>
                  <span className="ad-keycount">{session === "climb" ? `${found}/${ZONE_COUNT[z.k]}` : ZONE_COUNT[z.k]}</span>
                </div>
              );
            })}
            <p className="ad-note">
              Zones are Köppen–Geiger classes computed from monthly temperature and rainfall, so every point of land
              falls in exactly one. Regional names follow WWF ecoregions.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
